targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const isBulkUpdate = api.state.upgradeSessionType === 'bulk_app_update';

	if (api.state.selectedRadio === true || api.state.selectedRadio === 'true') {
        return {
            event: isBulkUpdate ? 'Select new upgrade plan in Bulk Update' : 'Select new upgrade plan',
            value: {
                'Session id': api.state.sessionId
            }
        };
    } else {
        return {
            event: isBulkUpdate ? 'Select existing upgrade plan in Bulk Update' : 'Select existing upgrade plan',
            value: {
                'Session id': api.state.sessionId,
                'Merged count': api.state.mergePayload?.selectedUpgradePlan?.length
            }
        };
    }
})

